# 브라우저 확장: axe DevTools · WAVE · Lighthouse 의 Accessibility 항목

/* 나쁨: 흐리게 만들려고 대비를 깎는다 */
.help { color: #bbb; }              /* 흰 배경에서 2.1:1 — 미달 */

/* 좋음: 대비는 지키고 위계는 크기·굵기·여백으로 */
.help { color: #6b7280; font-size: 0.875rem; }   /* 4.8:1 */

/* 비활성 상태도 읽을 수는 있어야 한다 */
.btn:disabled { opacity: 1; color: #6b7280; background: #f3f4f6; cursor: not-allowed; }

:focus-visible {
  outline: 3px solid #2563eb;
  outline-offset: 2px;      /* 요소에 딱 붙지 않게 — 훨씬 잘 보인다 */
  border-radius: 4px;
}

/* 어두운 배경 위에서도 보이게 두 겹으로 */
.dark :focus-visible {
  outline: 3px solid #fff;
  box-shadow: 0 0 0 6px #2563eb;
}

.sr-only {
  position: absolute; width: 1px; height: 1px;
  padding: 0; margin: -1px; overflow: hidden;
  clip-path: inset(50%); white-space: nowrap; border: 0;
}

/* display:none 이나 visibility:hidden 은 스크린리더에서도 사라진다 — 쓰면 안 된다 */

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* 또는 애니메이션을 조건부로 설계 */
@media (prefers-reduced-motion: no-preference) {
  .card { transition: transform .3s; }
}

function onRouteChange(page) {
  document.title = `${page.title} — 내 서비스`;      // ① 제목
  const main = document.querySelector('main');
  main.setAttribute('tabindex', '-1');
  main.focus();                                       // ② 초점을 본문으로
  announce(`${page.title} 화면으로 이동했습니다`);     // ③ 라이브 영역으로 알림
}

// 라이브 영역은 미리 만들어 두고 글자만 갈아 끼운다
function announce(msg) {
  document.getElementById('live-region').textContent = msg;
}
